/* READING — x2 : Read in Daily Life, 60 new items (dz001-dz060)
   diff : 2 = B2, 3 = C1, 4 = C2 */
(function () {
CONTENT.dl.push(
  { id: 'dz001', diff: 2, label: 'Email', doc: { kind: 'email', from: 'Student Health Centre', to: 'All students', subject: 'Flu vaccination clinic, November 4-5', body: `<p>Dear students,</p><p>The Health Centre will hold its annual flu vaccination clinic on Tuesday 4 and Wednesday 5 November in the Student Union ballroom, from 11 a.m. to 4 p.m. The vaccine is free for students who have paid the health fee; everyone else pays $25.</p><p>No appointment is needed, but you will have to fill in a short form on arrival, so please allow about 20 minutes. If you have an egg allergy, or have ever had a bad reaction to a vaccine, tell the nurse before you receive the injection. Students who cannot attend can book an appointment at the Health Centre itself after November 10.</p>` },
    qs: [
      { q: `Who has to pay $25 for the vaccine?`, o: [`All students who attend the clinic`, `Students who have not paid the health fee`, `Students with an egg allergy`, `Students who book an appointment`], a: 1, x: `« free for students who have paid the health fee; everyone else pays $25 ». Piège : ne pas généraliser à tous les étudiants.` },
      { q: `What are students with an egg allergy asked to do?`, o: [`Inform the nurse before the injection`, `Stay away from the clinic`, `Bring a letter from their doctor`, `Come on the second day only`], a: 0, x: `« tell the nurse before you receive the injection ». Rien n'est dit sur une interdiction ou un certificat.` },
      { q: `What can be inferred about a student who cannot come on November 4 or 5?`, o: [`They must wait until next year`, `They will have to pay double`, `They need a doctor's note`, `They can still be vaccinated at a later date`], a: 3, x: `Le Health Centre propose des rendez-vous après le 10 novembre : la vaccination reste possible.` },
    ] },
  { id: 'dz002', diff: 2, label: 'Notice', doc: { kind: 'notice', head: 'Campus Sustainability Office', title: 'Using the Campus Bike-Share', body: `<p>Bikes are available at six docking stations across campus. Register once online with your student ID, then unlock a bike with the app.</p><ul><li>The first 30 minutes of every ride are free; after that, each extra 15 minutes costs $1.</li><li>Bikes must be returned to a docking station. A bike left anywhere else will cost the rider a $10 fee.</li><li>Helmets are not provided, but we strongly recommend wearing one.</li></ul><p>If a bike is damaged, press the red button on the dock and choose another one.</p>` },
    qs: [
      { q: `How much would a 45-minute ride cost?`, o: [`Nothing`, `$1`, `$3`, `$10`], a: 1, x: `30 minutes gratuites, puis 1 $ pour les 15 minutes supplémentaires : 1 $.` },
      { q: `What happens if a rider leaves a bike outside a docking station?`, o: [`The bike is locked automatically`, `The rider has to take a safety course`, `The student ID is cancelled`, `The rider is charged a fee`], a: 3, x: `« A bike left anywhere else will cost the rider a $10 fee ».` },
      { q: `What does the notice suggest about helmets?`, o: [`They are compulsory`, `They are advised but not supplied`, `They can be rented at the dock`, `They are free at registration`], a: 1, x: `« not provided, but we strongly recommend » : conseillé, non fourni, non obligatoire.` },
    ] },
  { id: 'dz003', diff: 2, label: 'Text messages', doc: { kind: 'chat', head: 'Chat — Flat 9 (moving out)', msgs: [['Hana', 'The landlord\'s agent is coming for the inspection on Friday at 10. We only get the deposit back if everything is spotless.', '7:40 PM'], ['Marco', 'I\'ll do the kitchen tonight. Can you take the bathroom? Dario\'s parents are collecting his boxes on Thursday.', '7:44 PM'], ['Hana', 'Sure. The oven is the real problem though. Last tenants got charged $80 for it.', '7:46 PM'], ['Marco', 'Then let\'s rent a steam cleaner, it\'s only $20 at the hardware store.', '7:49 PM'], ['Hana', 'Good call. I\'ll split the cost three ways.', '7:50 PM']] },
    qs: [
      { q: `Why do the flatmates want to clean thoroughly?`, o: [`They want to get their deposit back`, `They are inviting guests`, `The landlord asked for a party`, `Dario's parents are visiting`], a: 0, x: `« We only get the deposit back if everything is spotless ».` },
      { q: `Why does Marco suggest renting a steam cleaner?`, o: [`The kitchen is too small to clean by hand`, `It is cheaper than buying one`, `They want to avoid a charge like the one the previous tenants paid`, `The agent requires it`], a: 2, x: `Le four a déjà coûté 80 $ aux anciens locataires ; louer l'appareil pour 20 $ est une précaution.` },
      { q: `Who will clean the bathroom?`, o: [`Marco`, `Dario`, `Dario's parents`, `Hana`], a: 3, x: `Marco prend la cuisine et demande à Hana : « Sure » = elle accepte la salle de bains.` },
    ] },
  { id: 'dz004', diff: 2, label: 'Event flyer', doc: { kind: 'notice', head: 'Careers Office presents', title: 'Alumni Networking Evening', body: `<p><b>Thursday 14 November, 6:30-9:00 p.m., Hartley Hall</b></p><p>Meet graduates working in banking, public policy and start-ups. Dress code: business casual.</p><p>Entry is free, but registration is required by November 8. Walk-ins will be admitted only if space remains. A résumé review desk will be open from 6:00 p.m. Light refreshments are provided; a cash bar opens after 8:00.</p>` },
    qs: [
      { q: `What may happen to someone who has not registered?`, o: [`They will be refused entry for sure`, `They must pay at the door`, `They might be let in if there is room`, `They will be added to the next event`], a: 2, x: `« Walk-ins will be admitted only if space remains » : possible mais non garanti.` },
      { q: `What can be inferred about the résumé review desk?`, o: [`It opens before the official start of the event`, `It closes at 6:30`, `It is only for banking students`, `It replaces the refreshments`], a: 0, x: `Le stand ouvre à 18 h, l'événement commence à 18 h 30.` },
      { q: `The word "walk-ins" refers to people who`, o: [`arrive on foot`, `leave early`, `come without registering in advance`, `work for the Careers Office`], a: 2, x: `walk-in = personne qui se présente sans réservation.` },
    ] },
  { id: 'dz005', diff: 2, label: 'Email', doc: { kind: 'email', from: 'University Print Shop', to: 'ENVS 220 students', subject: 'Your course pack is ready', body: `<p>Hello,</p><p>The course pack for ENVS 220 is now available at the print shop. It costs $34 and contains all the readings for weeks 1 to 12. Please bring your student ID when you collect it.</p><p>Please note that packs are printed on demand, so a replacement copy would take at least three working days. If you prefer to read online, the same texts will be posted on the course website from week 3 at no charge, although printing them in the campus labs costs 8 cents a page.</p>` },
    qs: [
      { q: `What is the main purpose of the email?`, o: [`To announce that a printed set of readings can be collected`, `To explain how to use the course website`, `To ask students to order a replacement`, `To change the price of the readings`], a: 0, x: `Le message annonce que le recueil de textes est prêt à être retiré.` },
      { q: `What does the email imply about losing the course pack?`, o: [`A new one would be free`, `A new one would not be available immediately`, `It cannot be replaced`, `The student must buy the online version`], a: 1, x: `Impression à la demande : « at least three working days » pour un remplacement.` },
      { q: `Why might a student choose the online version?`, o: [`It contains more readings`, `It is printed in colour`, `It is available from week 1`, `It does not cost anything unless it is printed`], a: 3, x: `Les textes en ligne sont gratuits ; seule l'impression en salle informatique coûte 8 cents la page.` },
    ] },
  { id: 'dz006', diff: 2, label: 'Apartment ad', doc: { kind: 'notice', head: 'Housing board — For rent', title: 'Bright studio near Eastgate Station', body: `<p><b>$950 per month</b>, utilities not included. Available from December 1.</p><p>12-month lease, one month's deposit. No pets, no smoking. Ten-minute walk to campus; shared laundry in the basement. Viewings on Saturday, 10 a.m. to noon, by appointment only. Contact Ms. Alvarez.</p>` },
    qs: [
      { q: `What is NOT covered by the monthly rent?`, o: [`The laundry`, `Utilities such as electricity and water`, `The deposit`, `Access to the station`], a: 1, x: `« utilities not included » : charges à payer en plus.` },
      { q: `Who would probably NOT be able to rent this studio?`, o: [`A student who works nearby`, `Someone who needs it for a year`, `A tenant who wants to move in during December`, `A person who owns a dog`], a: 3, x: `« No pets » : un propriétaire de chien est exclu.` },
      { q: `How can a person see the studio?`, o: [`By visiting at any time on Saturday`, `By booking a time slot for Saturday`, `By calling after December 1`, `By paying the deposit first`], a: 1, x: `« by appointment only » : uniquement sur rendez-vous, le samedi matin.` },
    ] },
  { id: 'dz007', diff: 2, label: 'Text messages', doc: { kind: 'chat', head: 'Chat — Presentation group', msgs: [['Elena', 'Quick update: Dr. Mills just emailed. Each group now gets 10 minutes instead of 15.', '2:15 PM'], ['Jonas', 'Ugh, we have 18 slides. We\'ll have to cut a lot.', '2:17 PM'], ['Elena', 'I think we can drop the history section. Nobody needs the background.', '2:18 PM'], ['Priya', 'Agreed, but keep the case study. That\'s what the grade is really about.', '2:21 PM'], ['Jonas', 'OK. I\'ll trim the slides tonight and we can rehearse at 4 tomorrow with a timer.', '2:22 PM']] },
    qs: [
      { q: `What news does Elena share?`, o: [`The presentation has been moved to tomorrow`, `The time for each presentation has been shortened`, `Dr. Mills wants a longer case study`, `The group has been given more slides`], a: 1, x: `10 minutes au lieu de 15 : la durée est réduite.` },
      { q: `What does Priya think about the case study?`, o: [`It should be shortened`, `It is too difficult`, `It is the most important part to keep`, `It should come first`], a: 2, x: `« keep the case study. That's what the grade is really about ».` },
      { q: `What will the group do tomorrow at 4?`, o: [`Hand in their slides`, `Practise their talk with a timer`, `Meet Dr. Mills`, `Write the history section`], a: 1, x: `« rehearse at 4 tomorrow with a timer » = répéter en chronométrant.` },
    ] },
  { id: 'dz008', diff: 2, label: 'Software notice', doc: { kind: 'notice', head: 'IT Services — Service notice', title: 'New VPN client required from Monday', body: `<p>The current VPN software will stop working on <b>Monday</b>. To connect to library databases and your files from home, you will need to install the new client, available from the IT Services website.</p><p>The installation takes about five minutes and requires you to restart your computer. Your username and password will not change. Students using a university laptop do not need to do anything: the update will be installed automatically overnight on Sunday.</p>` },
    qs: [
      { q: `Who has to install the new software themselves?`, o: [`Everyone, including laptop borrowers`, `Only staff members`, `People who use their own computer`, `Only people who forgot their password`], a: 2, x: `Les portables de l'université se mettent à jour automatiquement ; les autres doivent installer le client eux-mêmes.` },
      { q: `What will happen on Monday if a student has not updated the software?`, o: [`They will have to change their password`, `They will not be able to connect from home`, `Their account will be deleted`, `Their laptop will restart automatically`], a: 1, x: `L'ancien VPN cesse de fonctionner : plus d'accès à distance aux bases et aux fichiers.` },
    ] },
  { id: 'dz009', diff: 2, label: 'Delivery notice', doc: { kind: 'email', from: 'QuickPost Deliveries', to: 'Ms. Dubois', subject: 'We missed you', body: `<p>Dear Ms. Dubois,</p><p>We tried to deliver your parcel today at 2:10 p.m., but nobody was home to sign for it. The parcel has been taken to the QuickPost point at Greenway Pharmacy, 4 Mill Street, where it will be held for <b>seven days</b>.</p><p>To collect it, show photo ID and the tracking code below. If you would prefer another delivery attempt, reply to this email by 5 p.m. tomorrow and we will come back on Thursday. After seven days, unclaimed parcels are returned to the sender.</p>` },
    qs: [
      { q: `Why was the parcel not delivered?`, o: [`The address was wrong`, `The recipient was not at home to sign`, `The pharmacy was closed`, `The parcel was damaged`], a: 1, x: `« nobody was home to sign for it ».` },
      { q: `What must Ms. Dubois do to get a second delivery attempt?`, o: [`Go to the pharmacy`, `Phone the sender`, `Answer the email before 5 p.m. the next day`, `Pay a small fee`], a: 2, x: `« reply to this email by 5 p.m. tomorrow » pour une nouvelle tentative jeudi.` },
      { q: `What will happen if she does nothing for a week and a half?`, o: [`The parcel will go back to the sender`, `The parcel will be delivered on Thursday`, `The pharmacy will deliver it`, `She will receive a refund automatically`], a: 0, x: `Au bout de sept jours, les colis non retirés sont retournés à l'expéditeur.` },
    ] },
  { id: 'dz010', diff: 2, label: 'Library rules', doc: { kind: 'notice', head: 'Central Library — Floor guide', title: 'Quiet Study Rules', body: `<p><b>Floor 1 (Collaboration zone):</b> conversation and group work are welcome. Food in covered containers only.</p><p><b>Floor 2 (Quiet zone):</b> low-voice conversation only. Please put phones on silent.</p><p><b>Floor 3 (Silent zone):</b> no talking and no phone calls. Laptops may be used, but keyboards must be quiet. Staff may ask noisy visitors to move to a lower floor.</p><p>Belongings left unattended for more than 60 minutes may be moved to the front desk.</p>` },
    qs: [
      { q: `Where could two students discuss a project quietly in low voices?`, o: [`On Floor 1 only`, `On Floor 3`, `On Floor 2 or Floor 1`, `Nowhere in the library`], a: 2, x: `Floor 1 accueille les discussions, Floor 2 autorise la conversation à voix basse ; Floor 3 est silencieuse.` },
      { q: `What might happen to a bag left on a desk for two hours?`, o: [`It could be taken to the front desk`, `It will be thrown away`, `Its owner will be banned`, `It will be locked in the cafeteria`], a: 0, x: `Plus de 60 minutes sans surveillance : les affaires « may be moved to the front desk ».` },
      { q: `What does the notice imply about people who are too noisy on Floor 3?`, o: [`They will lose their library card`, `They can be asked to go to a lower floor`, `They must leave the building`, `They must pay a fine`], a: 1, x: `« Staff may ask noisy visitors to move to a lower floor ».` },
    ] },
  { id: 'dz011', diff: 2, label: 'Email', doc: { kind: 'email', from: 'Rachel Kim, Talent Team', to: 'Daniel Moreau', subject: 'Next steps: second interview', body: `<p>Dear Daniel,</p><p>Thank you for meeting us last Tuesday. The team enjoyed hearing about your internship, and we would like to invite you to a second interview with our department head, Mr. Salazar.</p><p>The interview will last about an hour and will include a short case exercise, so please bring a calculator. You can choose between Monday at 10 a.m. or Wednesday at 3 p.m. Let me know which you prefer by Friday. If neither works, tell me and I'll see what I can arrange.</p><p>Best regards,<br>Rachel</p>` },
    qs: [
      { q: `Why is Rachel writing to Daniel?`, o: [`To offer him the job`, `To reject his application`, `To invite him to another interview`, `To ask for a reference`], a: 2, x: `Elle l'invite à un deuxième entretien.` },
      { q: `Why should Daniel bring a calculator?`, o: [`The interview includes a practical exercise`, `He will take a maths test`, `The office has none`, `Mr. Salazar asked for one`], a: 0, x: `« a short case exercise » : un cas pratique est prévu.` },
      { q: `What can Daniel do if he cannot come on either day?`, o: [`Withdraw automatically`, `Come on any day he likes`, `Contact Rachel to look for another time`, `Send a colleague`], a: 2, x: `« tell me and I'll see what I can arrange ».` },
    ] },
  { id: 'dz012', diff: 2, label: 'Travel notice', doc: { kind: 'notice', head: 'Metro Rail — Service information', title: 'Line 4 closed this weekend', body: `<p>Because of track maintenance, <b>no trains will run between Central and Harbour stations on Saturday and Sunday</b>. Trains will operate normally between Harbour and North Park.</p><p>Free replacement buses will leave every ten minutes from the bus stops outside each affected station. Please allow an extra 25 minutes for your journey. Passengers with bicycles or large luggage are advised to use Line 2, as space on the buses is limited.</p>` },
    qs: [
      { q: `What will happen between Harbour and North Park?`, o: [`Buses will replace trains`, `Trains will run as usual`, `Trains will be slower`, `The line will be closed`], a: 1, x: `Seule la section Central-Harbour est fermée ; ailleurs les trains circulent normalement.` },
      { q: `Why are passengers with bicycles told to use Line 2?`, o: [`Line 2 is free`, `Bicycles are forbidden on trains`, `There is limited room on the replacement buses`, `Line 4 closes early`], a: 2, x: `« space on the buses is limited » : peu de place pour les vélos et les valises.` },
      { q: `What does "allow an extra 25 minutes" mean?`, o: [`Trains will leave 25 minutes late`, `Plan for the journey to take longer`, `Tickets are valid for 25 more minutes`, `Buses stop for 25 minutes`], a: 1, x: `allow = prévoir : le trajet durera environ 25 minutes de plus.` },
    ] },
  { id: 'dz013', diff: 2, label: 'Text messages', doc: { kind: 'chat', head: 'Chat — Sales team', msgs: [['Carla', 'Did you send your expense report for the Berlin trip? Finance wants everything by Friday.', '11:02 AM'], ['Tom', 'Almost. I\'m missing the receipt for the taxi from the airport. I paid cash.', '11:05 AM'], ['Carla', 'Without it they\'ll only reimburse the standard taxi rate, not what you actually paid.', '11:06 AM'], ['Tom', 'That\'s fine. It was about the same. I\'ll attach the hotel and train receipts today.', '11:09 AM'], ['Carla', 'Perfect. Submit it through the portal, not by email, or it gets lost.', '11:10 AM']] },
    qs: [
      { q: `What problem does Tom have?`, o: [`He cannot find the finance portal`, `He lost his hotel receipt`, `He has no proof of one of his expenses`, `He missed the deadline`], a: 2, x: `Il manque le reçu du taxi payé en liquide.` },
      { q: `What will Tom probably receive for the taxi?`, o: [`The standard rate`, `The exact amount he paid`, `Nothing`, `Double the standard rate`], a: 0, x: `Sans reçu, remboursement au tarif standard ; Tom juge que c'est à peu près équivalent.` },
      { q: `How should Tom send his report?`, o: [`By email to Finance`, `Through the online portal`, `On paper`, `Through Carla`], a: 1, x: `« Submit it through the portal, not by email ».` },
    ] },
  { id: 'dz014', diff: 2, label: 'Syllabus excerpt', doc: { kind: 'notice', head: 'CHEM 120 — Laboratory component', title: 'Lab reports (25% of final grade)', body: `<p>You will submit six lab reports during the term. Each is worth 5% of your final grade and is due one week after the experiment. Reports should be written individually, even though experiments are done in pairs.</p><p>Late reports lose 10% for each day. Your lowest report mark will be dropped, so only the best five count towards your grade. A report that is never submitted receives zero, and it may be dropped only if you have a documented reason for the absence.</p>` },
    qs: [
      { q: `How many reports count towards the final grade?`, o: [`Six`, `Five`, `Four`, `Ten`], a: 1, x: `Six rapports, mais la plus mauvaise note est supprimée : cinq comptent (5 x 5 % = 25 %).` },
      { q: `How should the reports be written?`, o: [`In pairs`, `By the whole class`, `By each student alone`, `By the lab assistant`], a: 2, x: `« written individually » même si les expériences se font à deux.` },
      { q: `What is true about a report that is never submitted?`, o: [`It is automatically dropped`, `It receives zero unless the absence is documented`, `It is replaced by the best report`, `It loses 10%`], a: 1, x: `Un rapport manquant vaut zéro et ne peut pas être « la note supprimée » sauf motif justifié.` },
    ] },
  { id: 'dz015', diff: 2, label: 'Email', doc: { kind: 'email', from: 'Treasurer, Hiking Club', to: 'Club members', subject: 'Membership fees due', body: `<p>Hi everyone,</p><p>A reminder that annual membership fees ($15) are due by the end of this month. The fee covers insurance for all club trips and a discount on equipment rental. Members who have not paid by then will not be able to join the November trip to Mount Hale.</p><p>You can pay by card at our next meeting or by bank transfer; the details are on our website. If paying is a problem for you, speak to me privately and we will find a solution. Thanks!</p>` },
    qs: [
      { q: `What does the membership fee cover?`, o: [`Transport to Mount Hale`, `Insurance and cheaper equipment hire`, `A free hiking guide`, `Meals during trips`], a: 1, x: `« insurance for all club trips and a discount on equipment rental ».` },
      { q: `What will happen to members who have not paid by the deadline?`, o: [`They will be asked to leave the club`, `They will pay $30`, `They will miss the next outing`, `They will lose their equipment`], a: 2, x: `Ils ne pourront pas participer à la sortie du Mount Hale en novembre.` },
      { q: `What is the treasurer's attitude towards members who have difficulty paying?`, o: [`Understanding and ready to help`, `Strict and unwilling to listen`, `Indifferent`, `Angry`], a: 0, x: `« speak to me privately and we will find a solution » : ton bienveillant.` },
    ] },
  { id: 'dz016', diff: 2, label: 'Health centre notice', doc: { kind: 'notice', head: 'Student Health Centre', title: 'Counselling Drop-in Sessions', body: `<p>Feeling stressed before exams? Our counsellors now offer <b>drop-in sessions</b> every Tuesday and Thursday from 1 to 3 p.m. No appointment is necessary, and sessions last up to 20 minutes.</p><p>Everything you say is confidential, except where there is a serious risk to your safety or to others. If you would like a longer conversation, the counsellor can help you book a regular appointment, usually within a week.</p>` },
    qs: [
      { q: `What is the main purpose of the notice?`, o: [`To advertise a new type of counselling service`, `To cancel appointments`, `To announce exam dates`, `To recruit counsellors`], a: 0, x: `Le centre annonce des consultations sans rendez-vous.` },
      { q: `When might a counsellor share information with someone else?`, o: [`When the student is stressed`, `When a teacher asks`, `When there is a serious safety risk`, `When the student fails an exam`], a: 2, x: `Confidentialité sauf risque grave pour la sécurité de l'étudiant ou d'autrui.` },
      { q: `What is a student advised to do if they need more than 20 minutes?`, o: [`Return the following day`, `Ask the counsellor to arrange a regular appointment`, `Stay after the drop-in session`, `Call the emergency number`], a: 1, x: `Le conseiller aide à réserver un rendez-vous classique, en général sous une semaine.` },
    ] },
  { id: 'dz017', diff: 2, label: 'Email', doc: { kind: 'email', from: 'Campus Dining', to: 'Meal plan holders', subject: 'Changes to meal plans next term', body: `<p>Dear students,</p><p>From January, the Gold meal plan will include 14 meals per week instead of 19, and the price will fall from $2,400 to $2,100 per term. Students who want to keep 19 meals per week can switch to the new Platinum plan at $2,550.</p><p>If you do not make a choice by December 5, you will be moved to the Gold plan automatically. Unused meals do not carry over to the following week under any plan.</p>` },
    qs: [
      { q: `What is changing about the Gold plan?`, o: [`It will have fewer meals but cost less`, `It will include more meals`, `It will become more expensive`, `It will be removed`], a: 0, x: `14 repas au lieu de 19, et 2 100 $ au lieu de 2 400 $.` },
      { q: `What happens to a student who makes no decision by December 5?`, o: [`They lose their meal plan`, `They keep 19 meals a week`, `They are placed on the Gold plan`, `They pay for Platinum`], a: 2, x: `« moved to the Gold plan automatically ».` },
      { q: `Which statement is true according to the email?`, o: [`Meals can be saved for later weeks`, `Platinum is cheaper than Gold`, `Meals not eaten in a week are lost`, `Plans cannot be changed`], a: 2, x: `« Unused meals do not carry over ».` },
    ] },
  { id: 'dz018', diff: 2, label: 'Text messages', doc: { kind: 'chat', head: 'Chat — Weekend trip', msgs: [['Sofia', 'Have you seen the forecast? Heavy rain on Saturday afternoon.', '5:30 PM'], ['Luis', 'Yes. Maybe we should hike in the morning and be back by noon?', '5:33 PM'], ['Sofia', 'Then we\'d need to leave at 6 a.m. Is everyone fine with that?', '5:34 PM'], ['Mina', 'I\'m fine with it, but I can\'t drive until eight. My car is at the garage until then.', '5:40 PM'], ['Luis', 'No problem, I\'ll drive. I\'ll pick you up on the way.', '5:41 PM']] },
    qs: [
      { q: `Why does Luis suggest hiking in the morning?`, o: [`He dislikes afternoon walks`, `It will rain later in the day`, `The trail closes at noon`, `Mina is busy in the afternoon`], a: 1, x: `La pluie est prévue samedi après-midi.` },
      { q: `Why can't Mina drive early?`, o: [`She does not have a licence`, `She is not coming`, `Her car is not available until eight`, `She prefers to sleep`], a: 2, x: `Sa voiture est au garage jusqu'à 8 h.` },
      { q: `What will probably happen on Saturday?`, o: [`The trip will be cancelled`, `Luis will drive and collect Mina`, `They will start at eight`, `Mina will drive the group`], a: 1, x: `Luis propose de conduire et de passer prendre Mina.` },
    ] },
  { id: 'dz019', diff: 2, label: 'Museum information', doc: { kind: 'notice', head: 'Riverside Museum of Science', title: 'Visitor Information', body: `<p><b>Opening hours:</b> Tuesday to Sunday, 10 a.m.-5 p.m. Closed on Mondays.</p><p><b>Tickets:</b> Adults $14; students and seniors $9; children under 6 free. Entry is free for everyone on the first Sunday of each month.</p><p>Photography without flash is welcome in all galleries except the Light and Colour exhibition. Large bags must be left in the cloakroom ($2). The planetarium show requires a separate ticket, bookable at the information desk.</p>` },
    qs: [
      { q: `When could an adult visit the museum without paying?`, o: [`Any Monday`, `On the first Sunday of the month`, `After 4 p.m. daily`, `On weekdays`], a: 1, x: `« free for everyone on the first Sunday of each month ».` },
      { q: `What is true about taking photographs?`, o: [`It is forbidden everywhere`, `Flash is allowed in all galleries`, `It is allowed except in one exhibition`, `It requires a special ticket`], a: 2, x: `Photos sans flash autorisées partout sauf dans « Light and Colour ».` },
      { q: `What can be inferred about the planetarium show?`, o: [`It is included in the standard ticket`, `It costs extra`, `It is only for children`, `It takes place on Mondays`], a: 1, x: `« requires a separate ticket » : supplément.` },
    ] },
  { id: 'dz020', diff: 2, label: 'Email', doc: { kind: 'email', from: 'Learning Centre', to: 'Aisha Rahman', subject: 'Tutoring appointment confirmed', body: `<p>Dear Aisha,</p><p>Your statistics tutoring session is confirmed for <b>Wednesday at 3:30 p.m.</b> in Room 112 with Mr. Okonkwo. Sessions last 45 minutes.</p><p>To make the most of your time, please email your questions or a copy of the problem you find difficult by Tuesday evening. If you need to cancel, you must do so at least 12 hours in advance through the online booking page; otherwise the session will count towards your monthly limit of four.</p>` },
    qs: [
      { q: `What should Aisha send by Tuesday evening?`, o: [`A payment`, `A signed form`, `Her questions or the problem she needs help with`, `Her timetable`], a: 2, x: `« email your questions or a copy of the problem ».` },
      { q: `What happens if Aisha cancels two hours before the session?`, o: [`Nothing, the session is simply cancelled`, `It will use one of her four monthly sessions`, `She will pay a $20 fee`, `The tutor will visit her at home`], a: 1, x: `Annulation hors délai de 12 h : la séance est décomptée de la limite mensuelle de quatre.` },
      { q: `Where will the session take place?`, o: [`Online`, `In the library`, `In the tutor's office`, `In Room 112`], a: 3, x: `La salle 112.` },
    ] },
  { id: 'dz021', diff: 2, label: 'Print credit notice', doc: { kind: 'notice', head: 'Campus Computing', title: 'Printing Credit: New Rules', body: `<p>Each student now receives <b>$10</b> of printing credit at the start of each term. Black-and-white pages cost 5 cents; colour pages cost 25 cents. Double-sided printing is cheaper: you pay for one sheet instead of two pages.</p><p>Unused credit does not carry over to the next term. When your credit runs out, you can add money at the machine in the foyer, but refunds are not possible. Please collect your documents within 24 hours, since uncollected print jobs are deleted.</p>` },
    qs: [
      { q: `Why is double-sided printing cheaper?`, o: [`It uses lower quality paper`, `The student pays for one sheet instead of two pages`, `It is only available in colour`, `It is free for the first ten pages`], a: 1, x: `Le texte explique : on paie une feuille au lieu de deux pages.` },
      { q: `What happens to credit that has not been used by the end of term?`, o: [`It is lost`, `It is refunded`, `It is carried over`, `It is given to another student`], a: 0, x: `« does not carry over » : perdu.` },
      { q: `What can be inferred about print jobs that nobody collects?`, o: [`They are mailed`, `They are removed after a day`, `They are charged twice`, `They are kept for a week`], a: 1, x: `Les impressions non récupérées en 24 h sont supprimées.` },
    ] },
  { id: 'dz022', diff: 3, label: 'Email', doc: { kind: 'email', from: 'Finance Office', to: 'All academic staff', subject: 'Travel expenses: revised rules from December 1', body: `<p>Dear colleagues,</p><p>Following the recent audit, the rules below will apply to all claims submitted from 1 December.</p><p>Meals will be reimbursed at a flat per diem of $60 for domestic and $85 for international travel; individual meal receipts are therefore no longer required, although the per diem is reduced by $20 for any day on which the host provides meals. Economy fares are the default. Business class may be approved only where a single flight exceeds eight hours and written authorisation has been obtained <i>before</i> booking. Hotel receipts remain mandatory.</p><p>Claims must be filed within 30 days of your return; anything submitted later will be processed only at the discretion of the Finance Director.</p>` },
    qs: [
      { q: `What is the main effect of the new rule on meals?`, o: [`Staff must keep every receipt`, `Meals are no longer reimbursed`, `Staff receive a fixed daily amount without receipts`, `Only international meals are covered`], a: 2, x: `« flat per diem » : montant forfaitaire, donc « individual meal receipts are no longer required ».` },
      { q: `Under which conditions could a member of staff fly business class?`, o: [`When the flight is longer than eight hours and approval was given in advance`, `When the host organisation pays`, `When the staff member files within 30 days`, `When no economy seats are left`], a: 0, x: `Deux conditions cumulatives : vol de plus de huit heures ET autorisation écrite préalable à la réservation.` },
      { q: `What can be inferred about a claim filed 45 days after the trip?`, o: [`It will automatically be rejected`, `It will be paid at a lower rate`, `It will be paid in full`, `It may still be accepted, but nobody can count on it`], a: 3, x: `Hors délai : traitement « at the discretion of the Finance Director » ; ni refus automatique ni droit acquis.` },
    ] },
  { id: 'dz023', diff: 3, label: 'Lease summary', doc: { kind: 'notice', head: 'Residential Lease Agreement — Summary of key terms', title: 'Deposit, notice and early termination', body: `<p><b>Deposit:</b> $1,800, held in a separate account and returned within 30 days of move-out, less any deductions for damage beyond normal wear and tear.</p><p><b>Notice:</b> The tenant must give 60 days' written notice of intention to vacate at the end of the term. If no notice is given, the lease renews automatically on a month-to-month basis at a rent 10% higher than the previous rate.</p><p><b>Early termination:</b> Permitted on payment of a fee equal to two months' rent, provided that 30 days' notice is given.</p>` },
    qs: [
      { q: `What happens if a tenant says nothing before the end of the lease term?`, o: [`The lease ends and the deposit is returned`, `The lease continues month by month at a higher rent`, `The lease renews for a further full year at the same rent`, `The landlord must give 60 days' notice`], a: 1, x: `Reconduction tacite au mois le mois avec un loyer majoré de 10 %.` },
      { q: `Which deduction from the deposit would be justified?`, o: [`Paint faded by years of sunlight`, `Carpet worn thin in the hallway`, `A large hole in a bedroom wall`, `Small marks left by picture hooks`], a: 2, x: `« beyond normal wear and tear » : seuls les dommages dépassant l'usure normale (un grand trou) justifient une retenue.` },
      { q: `What can be inferred about a tenant who leaves after six months with proper notice?`, o: [`They will lose the deposit completely`, `They will not pay anything extra`, `They will have to pay a penalty equal to two months' rent`, `They must find a replacement tenant`], a: 2, x: `Résiliation anticipée possible avec préavis de 30 jours, moyennant deux mois de loyer.` },
    ] },
  { id: 'dz024', diff: 3, label: 'Email', doc: { kind: 'email', from: 'Martha Lindgren, Graduate Recruitment', to: 'Ms. Okoye', subject: 'Re: Your offer, start date', body: `<p>Dear Ms. Okoye,</p><p>Thank you for your message and for your enthusiasm about joining us. I understand that you would prefer to start on 3 February rather than 6 January in order to sit your final exams.</p><p>We can accommodate this, although you should be aware that our main training programme begins in January. You would therefore join the following cohort, and part of the induction would be condensed. As for the salary, the band is fixed for graduate entrants and is not open to negotiation; we may, however, be able to revisit the relocation allowance.</p><p>Please confirm by Friday, after which the offer will lapse.</p><p>Kind regards,<br>Martha Lindgren</p>` },
    qs: [
      { q: `What compromise does the company offer?`, o: [`A higher salary`, `A later start with a shortened induction`, `A cancelled training programme`, `A start on 6 January with unpaid leave`], a: 1, x: `Début le 3 février, cohorte suivante, formation d'accueil condensée.` },
      { q: `What does the recruiter say about money?`, o: [`The salary can be increased if Ms. Okoye asks`, `Nothing can ever be changed`, `The relocation allowance might be discussed again`, `The salary will be lower for the later cohort`], a: 2, x: `Salaire non négociable, mais « we may, however, be able to revisit the relocation allowance ».` },
      { q: `How would you describe the tone of the email?`, o: [`Hostile and impatient`, `Warm but firm about limits and deadlines`, `Vague and uncommitted`, `Apologetic and uncertain`], a: 1, x: `Cordial (« thank you », « enthusiasm ») mais limites claires : salaire fixe et offre qui expire vendredi.` },
    ] },
  { id: 'dz025', diff: 3, label: 'Text messages', doc: { kind: 'chat', head: 'Chat — Client team', msgs: [['Ines', 'Client moved the call to 9 tomorrow. Do we still want to lead with the cost savings?', '4:48 PM'], ['Paul', 'I\'d hold off on that. Their CFO sounded lukewarm last time. I\'d rather open with the risk analysis and let the numbers speak.', '4:51 PM'], ['Ines', 'Fair, but if we bury the savings they might think we have nothing to offer on price.', '4:53 PM'], ['Paul', 'Not bury, just sequence. Slide 3, straight after the risk piece.', '4:54 PM'], ['Ines', 'Okay. I\'ll reshuffle the deck tonight. Can you vet the risk slides? I\'ve been staring at them too long.', '4:56 PM'], ['Paul', 'Send them over. I\'ll have them back by 8.', '4:57 PM']] },
    qs: [
      { q: `What does Paul propose?`, o: [`Dropping the cost savings altogether`, `Postponing the call`, `Presenting the risk analysis first and the savings shortly afterwards`, `Starting with the CFO's concerns`], a: 2, x: `Il veut ouvrir avec l'analyse de risque et placer les économies en slide 3 : « Not bury, just sequence ».` },
      { q: `What does "hold off on that" mean in this context?`, o: [`Do it without delay`, `Avoid doing it for now`, `Repeat it`, `Cancel the whole meeting`], a: 1, x: `hold off on = différer, s'abstenir pour le moment.` },
      { q: `What is Ines's concern about the savings?`, o: [`They are too large to be credible`, `The CFO has already rejected them`, `The client might think the firm cannot compete on price`, `They have not been calculated`], a: 2, x: `« they might think we have nothing to offer on price » si les économies sont enfouies.` },
    ] },
  { id: 'dz026', diff: 3, label: 'Software update notice', doc: { kind: 'notice', head: 'IT Services — Service notice', title: 'Retirement of the legacy grade portal', body: `<p>On 15 January the legacy grade portal will be retired and replaced by <i>Campus Hub</i>. All grades, transcripts and enrolment records have already been migrated; however, bookmarks and saved links to the old address will stop working.</p><p>Staff who use scripts or spreadsheets that pull data from the old portal will need to update them, since the new system does not support the previous export format. A read-only archive of the old portal will remain accessible until June for verification purposes, but no changes can be made to it.</p>` },
    qs: [
      { q: `What will stop working after 15 January?`, o: [`Student records`, `Links that point to the old portal`, `The ability to view transcripts`, `Access to Campus Hub`], a: 1, x: `Les données sont migrées ; ce sont les signets et liens vers l'ancienne adresse qui cesseront de fonctionner.` },
      { q: `What can be inferred about spreadsheets that import data from the old portal?`, o: [`They will need to be adapted`, `They will work with the archive only`, `They will be converted automatically`, `They will be deleted by IT`], a: 0, x: `Le nouveau système ne supporte pas l'ancien format d'export : il faut adapter les feuilles ou scripts.` },
      { q: `What is the archive intended for?`, o: [`Correcting grading errors`, `Entering late grades`, `Checking that data were transferred correctly`, `Replacing Campus Hub`], a: 2, x: `« read-only ... for verification purposes » : consultation seule, pour vérifier.` },
    ] },
  { id: 'dz027', diff: 3, label: 'Syllabus excerpt', doc: { kind: 'notice', head: 'MGMT 301 — Course policies', title: 'Group project (30% of final grade)', body: `<p>Eighty per cent of the project mark is shared by all group members. The remaining 20% is individual and is determined by confidential peer evaluations submitted at the end of the project. If a student's average peer score falls more than 15 points below the group mean, the instructor may adjust that student's mark irrespective of the group's overall result.</p><p>Students who feel that a teammate is not contributing are expected to raise the matter with me by week 8, not at the end of term, as complaints made late cannot be investigated fairly.</p>` },
    qs: [
      { q: `How is the individual part of the project mark determined?`, o: [`By the instructor's observation in class`, `By the group's overall result`, `By the number of slides each student prepares`, `By confidential evaluations from teammates`], a: 3, x: `« determined by confidential peer evaluations ».` },
      { q: `Why does the instructor ask students to report problems by week 8?`, o: [`Late complaints cannot be examined properly`, `The project ends in week 8`, `Peer evaluations are due then`, `Groups cannot change after week 8`], a: 0, x: `« complaints made late cannot be investigated fairly ».` },
      { q: `What can be inferred about a student who contributes very little to a successful group?`, o: [`They will receive the same mark as everyone else`, `Their mark may be lowered despite the group's success`, `They will be removed from the course`, `They will receive extra work`], a: 1, x: `L'ajustement individuel « irrespective of the group's overall result » est possible.` },
    ] },
  { id: 'dz028', diff: 3, label: 'Email', doc: { kind: 'email', from: 'Student Health Centre', to: 'Nursing and Education students on placement', subject: 'Immunisation records: deadline March 15', body: `<p>Dear students,</p><p>All students due to begin clinical or school placements next term must provide proof of immunisation against measles and chickenpox. If you cannot locate your childhood records, you may take a blood test at the Health Centre ($35; results within five working days), which will show whether you are immune.</p><p>Records must be uploaded to the secure portal by <b>March 15</b>. Students who have not done so will not be permitted to start their placement, and the programme office has no authority to waive this requirement, so please do not leave it until the last minute.</p>` },
    qs: [
      { q: `What can a student do if their vaccination records are missing?`, o: [`Start the placement anyway`, `Ask the programme office for an exemption`, `Pay for a blood test at the Health Centre`, `Be vaccinated again at no cost`], a: 2, x: `Le test sanguin (35 $) prouve l'immunité en l'absence de carnet.` },
      { q: `Why does the email say the programme office "has no authority to waive" the requirement?`, o: [`To show that no exceptions can be negotiated there`, `To suggest the office is not helpful`, `To say the requirement is new`, `To announce a change of rules`], a: 0, x: `Waive = renoncer à exiger : l'exigence est impossible à lever, donc inutile de demander.` },
      { q: `What is the likely consequence of submitting records after March 15?`, o: [`A small fine`, `A delay in starting the placement`, `A repeated blood test`, `Nothing at all`], a: 1, x: `Ils « will not be permitted to start their placement » : la prise de poste est retardée, voire empêchée.` },
    ] },
  { id: 'dz029', diff: 3, label: 'Credit card terms', doc: { kind: 'notice', head: 'Orion Bank — Student Credit Card, key terms', title: 'Interest and fees', body: `<p><b>Grace period:</b> Purchases are interest-free for up to 25 days, provided the full statement balance is paid by the due date. If only part of the balance is paid, interest is charged on all purchases from their transaction dates, not just on the unpaid amount.</p><p><b>Cash advances:</b> No grace period; interest accrues from the day of withdrawal.</p><p><b>Foreign transactions:</b> 2.5% fee on every purchase made outside the country.</p><p><b>Minimum payment:</b> the greater of $25 or 2% of the balance.</p>` },
    qs: [
      { q: `What happens if a cardholder pays only part of the statement balance?`, o: [`Interest applies only to the unpaid portion`, `Interest is charged on all purchases from the day they were made`, `The card is suspended`, `The cardholder pays only the foreign fee`], a: 1, x: `Le délai de grâce est perdu : intérêts sur tous les achats depuis leur date, pas seulement sur le solde impayé.` },
      { q: `How are cash advances treated differently from purchases?`, o: [`They cost 2.5% extra`, `They never earn interest`, `They have a longer grace period`, `Interest starts immediately`], a: 3, x: `« No grace period; interest accrues from the day of withdrawal ».` },
      { q: `Which customer would most likely pay no interest at all on purchases?`, o: [`Someone who pays the minimum each month`, `Someone who repays the entire statement every month by the due date`, `Someone who withdraws cash regularly`, `Someone who shops abroad`], a: 1, x: `Seul le remboursement intégral du relevé dans les délais préserve la gratuité.` },
    ] },
  { id: 'dz030', diff: 3, label: 'Customs notice', doc: { kind: 'email', from: 'GlobalExpress Customs Desk', to: 'Mr. Haddad', subject: 'Action needed: import charges on your parcel', body: `<p>Dear Mr. Haddad,</p><p>Your parcel from Singapore has arrived at our customs hub. Before we can release it, we must receive <b>$48.20</b> in import VAT and a $12 handling fee. Please pay online within 10 days. After that period the parcel will be returned to the sender at your expense.</p><p>Please note that customs may ask you for the original invoice if the declared value of the goods is questioned; delivery would then be delayed until the document has been checked.</p>` },
    qs: [
      { q: `Why has the parcel not yet been delivered?`, o: [`The sender used the wrong address`, `Charges must be paid before it can be released`, `It has been lost in Singapore`, `The invoice is missing`], a: 1, x: `Le colis est retenu tant que la TVA d'importation et les frais ne sont pas payés.` },
      { q: `What does "at your expense" mean in the first paragraph?`, o: [`You will have to bear the cost`, `You will be told the cost later`, `The company will pay`, `The sender will pay`], a: 0, x: `at your expense = à vos frais.` },
      { q: `Under which circumstances might delivery be postponed?`, o: [`If the customer pays within 10 days`, `If the customs authority doubts the declared value`, `If the parcel is returned`, `If the handling fee is paid late`], a: 1, x: `En cas de doute sur la valeur déclarée, on peut demander la facture : délai supplémentaire.` },
    ] },
  { id: 'dz031', diff: 2, label: 'Gym notice', doc: { kind: 'notice', head: 'University Fitness Centre', title: 'Freezing Your Membership', body: `<p>Members who will be away for at least four weeks, for example on an internship, a study-abroad programme or because of an injury, may freeze their membership.</p><p>Freeze requests must be made at the front desk, with a supporting document, at least five days before the freeze begins. A freeze costs $5 a month, and you cannot use the facilities while it is in place. Your membership end date is then extended by the length of the freeze. The maximum freeze is six months in any year.</p>` },
    qs: [
      { q: `What must a member do to freeze a membership?`, o: [`Pay the full year in advance`, `Call the centre on the day the freeze begins`, `Hand in a request and a document at least five days beforehand`, `Cancel and register again later`], a: 2, x: `Demande au comptoir, avec justificatif, au moins cinq jours avant le début du gel.` },
      { q: `What happens to the end date of the membership after a freeze?`, o: [`It is pushed back by the same length of time`, `It stays the same`, `It is brought forward`, `It is cancelled`], a: 0, x: `« extended by the length of the freeze » : la date de fin est repoussée d'autant.` },
      { q: `Who would NOT be able to use this option?`, o: [`A student with a broken leg who will be away for two months`, `A member leaving for a semester abroad`, `A student on a three-month internship`, `A member who will be travelling for two weeks`], a: 3, x: `Il faut une absence d'« at least four weeks » : deux semaines ne suffisent pas.` },
    ] },
  { id: 'dz032', diff: 2, label: 'Email', doc: { kind: 'email', from: 'Financial Aid Office', to: 'Kenji Mori', subject: 'Merit Scholarship renewal', body: `<p>Dear Kenji,</p><p>Your Merit Scholarship ($4,000 a year) is due for renewal. To keep it, you need a cumulative GPA of at least 3.2 and you must have completed 24 credits by the end of the academic year.</p><p>If your GPA is between 3.0 and 3.2, the scholarship will be continued for one more semester on probation. If it has not reached 3.2 by the end of that semester, the award will be withdrawn. Please confirm that you wish to renew by completing the online form before April 30.</p>` },
    qs: [
      { q: `What is the main purpose of the email?`, o: [`To explain what is needed to keep a scholarship`, `To announce that a scholarship has been withdrawn`, `To offer Kenji a new scholarship`, `To ask Kenji to change his courses`], a: 0, x: `Le message rappelle les conditions de renouvellement de la bourse.` },
      { q: `What would happen to a student with a 3.1 GPA and 24 credits?`, o: [`The scholarship would stop immediately`, `The amount would be doubled`, `The student would have to repay the money`, `The scholarship would continue for a semester under review`], a: 3, x: `GPA entre 3,0 et 3,2 : maintien d'un semestre « on probation ».` },
      { q: `What must Kenji do before April 30?`, o: [`Submit his transcript by post`, `Take an extra course`, `Meet his academic adviser`, `Complete a form to request renewal`], a: 3, x: `« confirm that you wish to renew by completing the online form ».` },
    ] },
  { id: 'dz033', diff: 2, label: 'Text messages', doc: { kind: 'chat', head: 'Chat — Café staff', msgs: [['Lena', `Could you cover my Saturday shift? I have a family wedding.`, '6:05 PM'], ['Omar', `I work at the bookshop until 2 that day, so I couldn't start before 3.`, '6:09 PM'], ['Lena', `Hmm. Mr. Barnes needs someone from noon for the lunch rush. Beth is away too.`, '6:11 PM'], ['Omar', `What about Raj? He's free in the morning. He could do noon to 3 and I'd take over after that.`, '6:14 PM'], ['Lena', `Brilliant! I'll tell Mr. Barnes once Raj has confirmed.`, '6:15 PM']] },
    qs: [
      { q: `Why does Lena want someone to take her shift?`, o: [`She has another job`, `She is ill`, `She will attend a family event`, `She is going on holiday`], a: 2, x: `« I have a family wedding ».` },
      { q: `What is the problem with Omar's first offer?`, o: [`He would arrive after the busiest time began`, `He does not like working Saturdays`, `He is not trained to work the lunch rush`, `Mr. Barnes does not know him`], a: 0, x: `Omar ne peut commencer qu'à 15 h alors qu'on a besoin de quelqu'un dès midi.` },
      { q: `What will Lena do next?`, o: [`Ask Beth to come back`, `Cancel the shift`, `Call the bookshop`, `Wait for Raj's answer before informing the manager`], a: 3, x: `« I'll tell Mr. Barnes once Raj has confirmed » : elle attend la confirmation de Raj.` },
    ] },
  { id: 'dz034', diff: 2, label: 'Parking notice', doc: { kind: 'notice', head: 'Campus Parking Services', title: 'New Permit Zones from September', body: `<p>Parking permits will now be sold by zone. <b>Zone A</b>, next to the lecture halls, costs $300 a year. <b>Zone B</b>, a ten-minute walk away, costs $180 a year, and a free shuttle runs every ten minutes.</p><p>A permit is linked to one vehicle. If you change your car, register the new licence plate online; this is free once per term. Visitors must buy a day pass ($6) from the machines. Vehicles without a valid permit or pass will be fined $45.</p>` },
    qs: [
      { q: `Why might a student prefer Zone B?`, o: [`It is closer to the lecture halls`, `It is cheaper and has a free shuttle`, `It is free for visitors`, `It never fills up`], a: 1, x: `Zone B coûte 180 $ au lieu de 300 $ et dispose d'une navette gratuite.` },
      { q: `What should a student do after buying a different car?`, o: [`Buy a new permit at full price`, `Pay a $45 fee`, `Park in Zone B only`, `Register the new plate online`], a: 3, x: `« register the new licence plate online » ; c'est gratuit une fois par trimestre.` },
      { q: `What does the notice say about visitors?`, o: [`They need to buy a day pass`, `They may park anywhere`, `They must park in Zone A`, `They get a free permit`], a: 0, x: `« Visitors must buy a day pass ($6) ».` },
    ] },
  { id: 'dz035', diff: 2, label: 'Email', doc: { kind: 'email', from: 'Conference Secretariat', to: 'Registered delegates', subject: 'Registration terms: Marine Biology Symposium', body: `<p>Dear delegate,</p><p>Thank you for your interest in the symposium. The early-bird rate of $220 applies until March 15; after that date, registration costs $310. The fee includes lunch on both days and the printed proceedings, but not accommodation.</p><p>If you cancel before April 1, you will receive a full refund. Between April 1 and April 20, we can refund 50%. After April 20 no refund is possible, but you are welcome to send a colleague in your place at no extra charge.</p>` },
    qs: [
      { q: `What is NOT included in the registration fee?`, o: [`Lunch`, `Access to the talks`, `The printed proceedings`, `A hotel room`], a: 3, x: `Le tarif couvre repas et actes imprimés, mais pas l'hébergement.` },
      { q: `How much would a delegate get back if they cancelled on April 10?`, o: [`Nothing`, `All of the fee`, `Half of the fee`, `The difference from the early-bird rate`], a: 2, x: `Entre le 1er et le 20 avril : remboursement de 50 %.` },
      { q: `What can someone do if they cannot attend and it is already April 25?`, o: [`Ask for a full refund`, `Postpone to next year`, `Pay a lower rate`, `Let someone else take their place`], a: 3, x: `Plus de remboursement, mais un collègue peut venir à sa place gratuitement.` },
    ] },
  { id: 'dz036', diff: 3, label: 'Bank email', doc: { kind: 'email', from: 'Harbor Credit Union', to: 'All members', subject: 'Changes to your current account from 1 March', body: `<p>Dear member,</p><p>We are writing to let you know about several changes to your current account. The monthly maintenance fee of $6 will continue to be waived for accounts with an average daily balance of $1,500 or more; until now, the threshold was $1,000.</p><p>We are also simplifying overdraft charges. Instead of a fee for each item returned, we will charge a single flat fee of $20 per day, however many transactions are affected. Overdraft protection linked to your savings account remains free. If you would rather not be covered by overdraft services, you can opt out online, in which case card purchases that exceed your balance will simply be declined. You do not need to do anything to keep your account as it is.</p>` },
    qs: [
      { q: `Which customer would start paying the maintenance fee because of the new rules?`, o: [`One whose average balance is $1,200`, `One whose average balance is $900`, `One who has opted out of overdraft`, `One with a linked savings account`], a: 0, x: `Avec 1 200 $ le client était exonéré (seuil 1 000 $) ; il ne l'est plus (seuil 1 500 $). Avec 900 $, il payait déjà.` },
      { q: `How do the new overdraft charges differ from the old ones?`, o: [`They are higher for each item`, `They apply only to cash withdrawals`, `They are removed completely`, `They are charged once a day at most`], a: 3, x: `Un forfait de 20 $ par jour, quel que soit le nombre d'opérations rejetées.` },
      { q: `What will happen to a member who opts out and spends more than their balance?`, o: [`The purchase will be refused`, `A $20 fee will be charged`, `Money will be taken from the savings account`, `The account will be closed`], a: 0, x: `« simply be declined » : l'achat par carte est refusé, sans frais.` },
    ] },
  { id: 'dz037', diff: 3, label: 'Equipment policy', doc: { kind: 'notice', head: 'Media Lab', title: 'Equipment loan policy', body: `<p>Cameras, microphones and lighting kits may be reserved up to 14 days ahead for a maximum of three days. Extensions are granted only if nobody else has booked the item.</p><p>A late return suspends borrowing privileges for as many days as the item was overdue; two late returns in a single term result in a loss of privileges until the end of that term. Borrowers are liable for repair or replacement costs where an item is lost or damaged through negligence, but not for faults arising from normal use.</p>` },
    qs: [
      { q: `Under what circumstances can a borrower keep a camera for more than three days?`, o: [`When the course instructor approves`, `When the camera is needed for a final project`, `When the borrower pays a deposit`, `When nobody else has reserved it`], a: 3, x: `« Extensions are granted only if nobody else has booked the item ».` },
      { q: `What is the consequence of returning a microphone two days late?`, o: [`Borrowing is suspended for two days`, `The borrower pays for a new microphone`, `The borrower loses privileges for the term`, `Nothing, unless it happens twice`], a: 0, x: `Suspension d'autant de jours que de retard : deux jours. La perte pour le trimestre vient au deuxième retard.` },
      { q: `For which problem would a student most probably have to pay?`, o: [`A battery that stops holding charge after months of use`, `A lens cracked after being left on the edge of a table`, `A tripod that wears out after regular use`, `A cable that fails because of a manufacturing defect`], a: 1, x: `Seuls les dommages dus à la négligence sont facturés, pas l'usure normale ni les défauts.` },
    ] },
  { id: 'dz038', diff: 3, label: 'Text messages', doc: { kind: 'chat', head: 'Chat — Finance team', msgs: [['Priya', `Heads-up: the auditors have flagged the Q3 accruals again. Not a big deal in itself, but it'd be good to have a clean answer before the review meeting.`, '10:12 AM'], ['Marcus', `Isn't that the same issue as in June? I thought we'd settled it by reclassifying the consulting fees.`, '10:14 AM'], ['Priya', `Supposedly. But they're asking why the reclassification never made it into the opening balance.`, '10:16 AM'], ['Marcus', `Right, that one's on me. I never carried the adjustment forward. I'll draft a reply, though I'd rather you didn't forward it until Dana has glanced over it.`, '10:19 AM'], ['Priya', `Fine by me. She's out until Thursday, so we have some slack.`, '10:20 AM']] },
    qs: [
      { q: `What are the auditors asking about this time?`, o: [`Why the consulting fees were classified wrongly in June`, `Why Dana was not consulted`, `Why the Q3 report was submitted late`, `Why a correction does not show in the opening balance`], a: 3, x: `La reclassification n'a jamais été reportée dans le solde d'ouverture.` },
      { q: `What does Priya's word "Supposedly" suggest?`, o: [`She doubts that the matter was really settled`, `She does not understand the question`, `She is sure the issue was resolved`, `She wants to blame Marcus`], a: 0, x: `« Supposedly » exprime un doute : c'est ce qu'on dit, mais ce n'est pas certain.` },
      { q: `What does Marcus ask Priya to do?`, o: [`Wait for Dana's review before sending the reply`, `Send the reply immediately`, `Write the reply herself`, `Contact the auditors on Thursday`], a: 0, x: `« I'd rather you didn't forward it until Dana has glanced over it ».` },
    ] },
  { id: 'dz039', diff: 3, label: 'Syllabus excerpt', doc: { kind: 'notice', head: 'ECON 240 — Course policies', title: 'Late work and flex days', body: `<p>Each student has three <i>flex days</i> to use during the term. Using one extends a problem-set deadline by 24 hours, no explanation required; you must declare it by email before the original deadline. Flex days may be combined on a single assignment.</p><p>Once they are used up, late work loses 15 points per day. Extensions beyond this system are granted only in documented emergencies and do not use up flex days. Flex days cannot be applied to the final project.</p>` },
    qs: [
      { q: `How long an extension would a student get by using two flex days on one problem set?`, o: [`24 hours`, `72 hours`, `48 hours`, `None, because they cannot be combined`], a: 2, x: `Un jour de flexibilité = 24 h, et ils sont cumulables : 48 h.` },
      { q: `How does an emergency extension differ from a flex day?`, o: [`It requires no email`, `It is available only before the deadline`, `It lasts exactly 24 hours`, `It does not reduce the number of flex days left`], a: 3, x: `Les prolongations pour urgence documentée « do not use up flex days ».` },
      { q: `What can be inferred about the final project?`, o: [`It cannot be delayed through flex days even if some remain`, `It is graded without penalties`, `It is worth more than problem sets`, `It must be submitted early`], a: 0, x: `Les flex days ne s'appliquent pas au projet final, même s'il en reste.` },
    ] },
  { id: 'dz040', diff: 3, label: 'Email', doc: { kind: 'email', from: 'Gerald Whitcombe, Landlord', to: 'Mr. and Ms. Tran', subject: 'Notice of rent adjustment', body: `<p>Dear Mr. and Ms. Tran,</p><p>In accordance with the terms of your lease, I am writing to give notice that the rent for the apartment will rise from $1,350 to $1,410 a month with effect from 1 July. This follows increases in property taxes and in the cost of insuring the building. The adjustment is within the 5% annual limit set by local ordinance.</p><p>If you wish to discuss the matter, please contact me before 15 May. I cannot promise to alter the figure, but I would be willing to consider a two-year lease with the increase phased in over that period.</p>` },
    qs: [
      { q: `What reason does the landlord give for the increase?`, o: [`The apartment has been renovated`, `Tenants in nearby buildings pay more`, `His costs of owning the building have gone up`, `The lease requires an increase every year`], a: 2, x: `Hausse des taxes foncières et de l'assurance de l'immeuble.` },
      { q: `What does the email say about the legality of the increase?`, o: [`It exceeds the limit but is permitted by the lease`, `It is not covered by any rule`, `It has been approved by the city`, `It stays below the legal ceiling`], a: 3, x: `« within the 5% annual limit » : en dessous du plafond légal (60 $ sur 1 350 $, soit environ 4,4 %).` },
      { q: `What does the landlord offer the tenants?`, o: [`To keep the rent unchanged for a year`, `To lower the increase if they pay quickly`, `To discuss spreading the rise over a longer lease`, `To pay for repairs`], a: 2, x: `Il ne promet pas de changer le montant, mais envisagerait un bail de deux ans avec hausse échelonnée.` },
    ] },
  { id: 'dz041', diff: 3, label: 'Insurance summary', doc: { kind: 'notice', head: 'Voyager Travel Insurance — Summary of cover', title: 'Cancellation and baggage', body: `<p><b>Trip cancellation</b> is covered where it results from the illness, injury or death of the insured person or a close relative, provided that a doctor's certificate is supplied. Not covered: pre-existing conditions that were not stable in the 90 days before purchase; cancellation owing to a change of mind or work commitments; and losses arising from circumstances already known at the time of purchase.</p><p><b>Baggage</b> is covered up to $1,500, with a limit of $300 per item. Items of high value, such as jewellery and electronics, are covered only when carried in hand luggage.</p>` },
    qs: [
      { q: `Which cancellation would probably be covered?`, o: [`A traveller decides she would prefer a different destination`, `A traveller's brother is hospitalised, and a doctor confirms it in writing`, `A traveller's employer refuses to grant leave`, `A traveller cancels because an airline strike was announced before she booked`], a: 1, x: `Maladie d'un proche avec certificat médical : couvert. Les autres cas sont des exclusions.` },
      { q: `Why would a strike announced before purchase not be covered?`, o: [`Strikes are never insured`, `The airline would pay instead`, `The strike lasted less than 90 days`, `The traveller knew of the circumstances when buying the policy`], a: 3, x: `« circumstances already known at the time of purchase » : exclusion.` },
      { q: `What would happen if a laptop in a checked suitcase were stolen?`, o: [`It would not be covered`, `It would be reimbursed up to $1,500`, `It would be reimbursed up to $300`, `It would be replaced by the airline`], a: 0, x: `Les objets de valeur ne sont couverts qu'en bagage à main.` },
    ] },
  { id: 'dz042', diff: 3, label: 'Email', doc: { kind: 'email', from: 'Sandra Kruger, Recruitment', to: 'Mr. Aoki', subject: 'Your application: Analyst position', body: `<p>Dear Mr. Aoki,</p><p>Thank you for taking the time to interview for the Analyst position. After careful consideration, we have decided to offer the role to another candidate, whose experience in credit modelling more closely matches the immediate needs of the team.</p><p>This was far from an easy decision. Your case-study presentation was among the strongest we saw, and several panellists remarked on the clarity of your answers under questioning. We would like to keep your details on file for six months, as we expect a further opening in the autumn, unless you ask us not to. I would be happy to arrange a short call if you would find more detailed feedback useful.</p><p>With best wishes,<br>Sandra Kruger</p>` },
    qs: [
      { q: `Why was Mr. Aoki not offered the job?`, o: [`His presentation was weak`, `He answered the questions poorly`, `The position was cancelled`, `Another candidate's experience was more directly relevant`], a: 3, x: `L'autre candidat a une expérience en modélisation du crédit qui correspond mieux au besoin immédiat.` },
      { q: `What can be inferred about the company's view of Mr. Aoki?`, o: [`They were impressed by him despite not hiring him`, `They doubt his honesty`, `They think he is too senior`, `They found him unprepared`], a: 0, x: `« far from an easy decision », « among the strongest » : une bonne impression, malgré le refus.` },
      { q: `What will happen to Mr. Aoki's details if he does not reply?`, o: [`They will be deleted at once`, `They will be kept for a year`, `They will be sent to other firms`, `They will be kept for six months`], a: 3, x: `Conservation six mois « unless you ask us not to » : sans réponse, le dossier est gardé.` },
    ] },
  { id: 'dz043', diff: 3, label: 'Privacy notice', doc: { kind: 'notice', head: 'Learnly — Policy update', title: 'Changes to our Privacy Policy, effective 1 April', body: `<p>From 1 April we will share anonymised usage data with Analytica Ltd., a third-party provider, in order to improve our course recommendations. We will not share your name, email address or grades.</p><p>You may opt out under <b>Settings &gt; Privacy</b>. Opting out will not restrict access to any feature of the platform, although the recommendations you see will be less tailored to you. Continued use of the platform after 1 April constitutes acceptance of the updated policy.</p>` },
    qs: [
      { q: `What information will be passed to the outside company?`, o: [`Students' grades`, `Data on how the platform is used, without identifying individuals`, `Names and email addresses`, `Payment details`], a: 1, x: `« anonymised usage data » ; nom, e-mail et notes ne sont pas partagés.` },
      { q: `What is the consequence of opting out?`, o: [`Some features are blocked`, `The account is closed`, `Course suggestions are less personalised`, `Fees are increased`], a: 2, x: `Aucun accès perdu, mais des recommandations moins ciblées.` },
      { q: `How is acceptance of the new policy shown?`, o: [`By signing a form`, `By simply continuing to use the platform`, `By replying to an email`, `By ticking a box in Settings`], a: 1, x: `« Continued use ... constitutes acceptance » : l'acceptation découle de l'usage.` },
    ] },
  { id: 'dz044', diff: 3, label: 'Text messages', doc: { kind: 'chat', head: 'Chat — Procurement', msgs: [['Ravi', `Legal flagged clause 7 in the Northwind contract. If we terminate before the end of year two, we owe 60% of the remaining fees.`, '3:02 PM'], ['Hui', `That's steep. Is it negotiable?`, '3:04 PM'], ['Ravi', `They said "in principle", which in sales-speak usually means no.`, '3:05 PM'], ['Hui', `Ha. Then maybe we should look again at Calder. Less polished, but about 20% cheaper.`, '3:08 PM'], ['Ravi', `True, though their references were thin. I'd want a pilot before committing.`, '3:10 PM'], ['Hui', `A pilot would eat into the timeline. Let's put both options to Fatima tomorrow and let her decide.`, '3:12 PM']] },
    qs: [
      { q: `How does Ravi interpret the supplier's answer "in principle"?`, o: [`As a sign that the clause can be removed`, `As evidence that the contract is already signed`, `As a probable refusal to change the clause`, `As an offer of a discount`], a: 2, x: `« in sales-speak usually means no » : en pratique, un refus poli.` },
      { q: `What worries Ravi about Calder?`, o: [`Its prices are too high`, `It has little proof of a good track record`, `Its contract is too long`, `Its staff are unprofessional`], a: 1, x: `« their references were thin » : peu de références solides.` },
      { q: `What do the two colleagues decide?`, o: [`To sign with Northwind immediately`, `To run a pilot with Calder`, `To let Fatima choose between the options`, `To cancel the project`], a: 2, x: `« put both options to Fatima ... and let her decide ». Le pilote est jugé trop long.` },
    ] },
  { id: 'dz045', diff: 3, label: 'Health notice', doc: { kind: 'notice', head: 'Student Health Centre', title: 'Stomach virus reported in Alder and Birch Halls', body: `<p>Several cases of a stomach virus consistent with norovirus have been reported in two residence halls. Symptoms include sudden vomiting, diarrhoea and cramps, and usually clear up within one to two days. Because the illness is viral, antibiotics will not help.</p><p>The best protection is washing your hands thoroughly with soap and water; alcohol gel is <b>not</b> an adequate substitute. If you are ill, stay in your room and do not attend classes or use the dining hall until 48 hours after your last symptom. Dining Services will deliver meals to affected students. Contact us if you cannot keep fluids down for more than 24 hours or show signs of dehydration.</p>` },
    qs: [
      { q: `Why does the notice advise soap and water rather than alcohol gel?`, o: [`Gel is not as effective against this virus`, `Gel is not available in the halls`, `Soap is cheaper`, `Gel causes dehydration`], a: 0, x: `« alcohol gel is not an adequate substitute » : insuffisant contre ce virus.` },
      { q: `When may a student who has been ill go back to class?`, o: [`As soon as the vomiting stops`, `After a full week`, `After 48 hours without symptoms`, `After taking antibiotics`], a: 2, x: `« until 48 hours after your last symptom ». Piège : l'arrêt des symptômes ne suffit pas.` },
      { q: `Why are antibiotics not recommended?`, o: [`They are too expensive`, `They cause cramps`, `They only work if taken early`, `The illness is caused by a virus`], a: 3, x: `« Because the illness is viral, antibiotics will not help ».` },
    ] },
  { id: 'dz046', diff: 3, label: 'Email', doc: { kind: 'email', from: 'Prof. Hellman', to: 'BIOL 210 students', subject: 'Midterm: two sittings on Thursday 12 March', body: `<p>Dear class,</p><p>Owing to a booking clash, we can no longer seat everyone in a single room. The midterm will therefore be held in two sittings on the same day: 9 a.m. for surnames A to L and 2 p.m. for surnames M to Z.</p><p>The two papers differ in wording but are of equal difficulty. Please do not discuss the paper with anyone until 5 p.m., so that no group gains an advantage. Students with approved accommodations such as extra time will sit the exam in Room 14 at 9 a.m., whatever their surname. If this arrangement creates a genuine conflict with another commitment, write to me by Friday, with evidence.</p>` },
    qs: [
      { q: `Why is the exam being split into two sittings?`, o: [`There are too many students for the planned room`, `The professor wants a harder exam`, `Students asked for a choice of times`, `Half the class is on a field trip`], a: 0, x: `« a booking clash » : on ne peut plus tout le monde asseoir dans une seule salle.` },
      { q: `When and where will a student with surname Novak and extra time sit the exam?`, o: [`At 2 p.m. in the main room`, `At 9 a.m. in Room 14`, `At 2 p.m. in Room 14`, `At 9 a.m. in the main room`], a: 1, x: `Les aménagements ont lieu à 9 h en salle 14, quel que soit le nom.` },
      { q: `Why are students told not to discuss the paper until 5 p.m.?`, o: [`To protect the professor's copyright`, `To prevent noise in the corridors`, `To keep the conditions fair for both groups`, `To let the professor mark first`], a: 2, x: `« so that no group gains an advantage » : équité entre les deux groupes.` },
    ] },
  { id: 'dz047', diff: 3, label: 'Subscription notice', doc: { kind: 'notice', head: 'NovaSuite — Account notice', title: 'Your annual plan renews on 3 March', body: `<p>Your plan will renew automatically on 3 March at the standard price of $99; the $79 you paid last year was an introductory rate. To avoid being charged, cancel at least 48 hours before the renewal date under <b>Account &gt; Billing</b>.</p><p>A cancellation made after that deadline will take effect only at the end of the next paid year, and no refund is available. If you cancel in time, you keep full access until the end of the period you have already paid for.</p>` },
    qs: [
      { q: `Why will the renewal price be different from last year's?`, o: [`The plan now includes more features`, `Last year's price was a special offer for new customers`, `There is a penalty for late payment`, `Taxes have increased`], a: 1, x: `Le tarif de 79 $ était promotionnel ; le prix normal est de 99 $.` },
      { q: `What happens to a subscriber who cancels on 2 March?`, o: [`They get a refund the following day`, `They lose access immediately`, `They pay $79`, `They are charged for another year, but not for the one after`], a: 3, x: `Annulation tardive (moins de 48 h) : prise d'effet à la fin de l'année suivante, sans remboursement.` },
      { q: `What does a subscriber who cancels in time keep?`, o: [`Access until the paid period ends`, `A discount next year`, `A partial refund`, `Nothing after cancelling`], a: 0, x: `« you keep full access until the end of the period you have already paid for ».` },
    ] },
  { id: 'dz048', diff: 3, label: 'Email', doc: { kind: 'email', from: 'Sleep and Memory Lab', to: 'Study participant', subject: 'Your session on Friday', body: `<p>Dear participant,</p><p>Thank you for signing up. Your session will last about 90 minutes. You will wear a headband that records brain activity; it is entirely non-invasive. We ask you to avoid caffeine for 12 hours beforehand.</p><p>You will receive $30 in cash at the end. You are free to withdraw at any point without giving a reason, in which case you will be paid in proportion to the time you completed. Your responses are stored under a code number, with your name kept separately in a locked file, and results will be published only in aggregate form.</p>` },
    qs: [
      { q: `What is a participant asked to do before the session?`, o: [`Sleep for at least eight hours`, `Avoid caffeine for twelve hours`, `Sign a form at the lab`, `Bring a friend`], a: 1, x: `« avoid caffeine for 12 hours beforehand ».` },
      { q: `What happens if a participant leaves halfway through?`, o: [`Nothing is paid`, `The full $30 is paid`, `Payment is reduced to match the time spent`, `Another session must be scheduled`], a: 2, x: `Paiement au prorata du temps accompli (« in proportion »).` },
      { q: `How does the lab protect participants' identities?`, o: [`Names are published without data`, `Responses are linked to codes and names stored apart`, `Participants answer under false names`, `Data are destroyed after each session`], a: 1, x: `Données sous numéro de code ; noms conservés séparément ; résultats agrégés.` },
    ] },
  { id: 'dz049', diff: 3, label: 'Residence policy', doc: { kind: 'notice', head: 'Residence Life', title: 'Guests and quiet hours', body: `<p>Each resident may host overnight guests for up to three nights a month, provided the guest is registered at the front desk by 10 p.m. Guests must be 18 or over unless they are family members. Hosts bear full responsibility for their guests' conduct: a guest's breach of the rules will be treated as the host's own.</p><p>Quiet hours run from 10 p.m. to 7 a.m. Sunday to Thursday and from midnight to 9 a.m. on Friday and Saturday nights. During exam weeks, quiet hours apply around the clock on floors designated as quiet floors.</p>` },
    qs: [
      { q: `What happens if a guest breaks a residence rule?`, o: [`Only the guest is sanctioned`, `The host is held accountable`, `The front desk is fined`, `Nothing, if the guest is a visitor for one night`], a: 1, x: `« treated as the host's own » : le résident hébergeant est tenu pour responsable.` },
      { q: `Which guest could be registered?`, o: [`A 17-year-old friend`, `A friend who was registered after midnight`, `A 15-year-old cousin`, `A friend staying a fourth night`], a: 2, x: `Un mineur est accepté s'il fait partie de la famille ; les autres cas enfreignent une règle (âge, heure, quota).` },
      { q: `Which statement is true about noise at 11 p.m. on a Saturday outside exam weeks?`, o: [`Quiet hours are already in force`, `Quiet hours apply on quiet floors only`, `Quiet hours have not yet started`, `Quiet hours do not apply at weekends`], a: 2, x: `Le samedi soir, le silence ne commence qu'à minuit : à 23 h, il n'est pas encore en vigueur. Il s'applique bien le week-end.` },
    ] },
  { id: 'dz050', diff: 3, label: 'Email', doc: { kind: 'email', from: 'TechHaven Customer Care', to: 'Ms. Varga', subject: 'Re: Screen flickering on your TX-14', body: `<p>Dear Ms. Varga,</p><p>Thank you for contacting us about your TX-14 laptop. Our return window is 30 days from delivery. As yours was delivered on 2 October, it has now expired, so we are unable to accept a change-of-mind return.</p><p>However, the fault you describe falls under the one-year manufacturer's warranty, which entitles you to a repair or, if that proves impossible, a replacement. Please back up your files first, since a repair may involve a factory reset. A prepaid shipping label is attached. Repairs normally take seven to ten working days.</p>` },
    qs: [
      { q: `Why can the company not take the laptop back as a return?`, o: [`The fault is not covered`, `The deadline for returns has passed`, `The customer damaged it`, `The model is no longer sold`], a: 1, x: `Fenêtre de retour de 30 jours dépassée depuis la livraison du 2 octobre.` },
      { q: `What is Ms. Varga entitled to?`, o: [`A refund`, `A discount on a new laptop`, `A repair, or a replacement if repair fails`, `Free upgrade to a better model`], a: 2, x: `La garantie constructeur ouvre droit à réparation, sinon à remplacement.` },
      { q: `Why is she asked to back up her files?`, o: [`The courier will not accept laptops with data`, `Repairs can erase the contents`, `The warranty requires it`, `The company wants to copy them`], a: 1, x: `« a repair may involve a factory reset » : les données risquent d'être effacées.` },
    ] },
  { id: 'dz051', diff: 4, label: 'Email', doc: { kind: 'email', from: 'Prof. Ingrid Solheim', to: 'Camille Durand', subject: 'Chapter 3 draft', body: `<p>Dear Camille,</p><p>Thank you for the draft of Chapter 3. There is a great deal here to admire: the dataset is original, and your handling of survey attrition is more careful than most.</p><p>That said, I did find myself wondering whether the chapter is quite doing the work you want it to. The claim that remote work <i>fundamentally</i> reshapes wage bargaining sits rather awkwardly beside Table 3.4, where the interaction coefficients are small and, as you concede in a footnote, statistically indistinguishable from zero. I would not suggest abandoning the claim, but I would urge you either to temper it or to devise a sharper test.</p><p>Could you bring a revised outline to our next meeting? There is no need to polish the prose; it is the logic I am interested in.</p>` },
    qs: [
      { q: `What is the supervisor's main reservation?`, o: [`The data were collected carelessly`, `The prose of the chapter is unclear`, `The survey has too many missing respondents`, `The conclusion goes further than the results justify`], a: 3, x: `L'affirmation « fundamentally » est plus forte que ce que montrent des coefficients proches de zéro.` },
      { q: `How should the phrase "I did find myself wondering whether the chapter is quite doing the work you want" be understood?`, o: [`As a mild remark on a minor point`, `As a polite way of expressing a serious doubt`, `As a compliment on the chapter`, `As a request for a clearer title`], a: 1, x: `Euphémisme académique : une critique de fond adoucie par des formules indirectes.` },
      { q: `What does the supervisor ask Camille to prepare?`, o: [`A polished new version of the chapter`, `A new dataset`, `A statement dropping the claim`, `An outline that focuses on the argument`], a: 3, x: `Un plan révisé : « it is the logic I am interested in », pas la rédaction.` },
    ] },
  { id: 'dz052', diff: 4, label: 'Journal policy', doc: { kind: 'notice', head: 'Journal of Applied Economics', title: 'Submission policy: prior dissemination and conflicts of interest', body: `<p>Manuscripts must not be under consideration elsewhere. The posting of a working paper or preprint on a recognised repository is not regarded as prior publication, but it must be disclosed at the time of submission.</p><p>Authors must declare any financial relationship with a party that has a stake in the outcome of the research, even where they judge that the relationship had no bearing on their conclusions. Whether it did is not for authors to decide; that judgement belongs to editors and referees. Should an undeclared relationship come to light after publication, the article may be retracted regardless of whether its findings are affected.</p>` },
    qs: [
      { q: `What is the journal's position on preprints?`, o: [`They disqualify a manuscript`, `They are acceptable provided they are reported`, `They need the editor's permission beforehand`, `They are acceptable only after publication`], a: 1, x: `Un preprint n'est pas une publication antérieure, mais il faut le déclarer à la soumission.` },
      { q: `Why must authors declare relationships they consider irrelevant?`, o: [`Because the journal wants to publish sponsor names`, `Because such relationships always bias results`, `Because evaluating possible influence is the job of editors and referees`, `Because referees must contact the sponsor`], a: 2, x: `Ce n'est pas aux auteurs de juger de l'influence : « that judgement belongs to editors and referees ».` },
      { q: `What could happen if an undeclared relationship is discovered after publication?`, o: [`The article may be withdrawn even if its results are sound`, `The article is withdrawn only if the results were wrong`, `The authors must simply add a footnote`, `Nothing, since the article is already published`], a: 0, x: `« retracted regardless of whether its findings are affected » : sanction indépendante de la validité des résultats.` },
    ] },
  { id: 'dz053', diff: 4, label: 'Text messages', doc: { kind: 'chat', head: 'Chat — Regional desk', msgs: [['Nadia', `Have you read the "organisational realignment" memo? Apparently we're "sunsetting" the regional desk.`, '1:02 PM'], ['Tomas', `Ah yes. Nothing says "we value you" like a verb borrowed from software. I notice nobody says who's actually being moved.`, '1:04 PM'], ['Nadia', `Page 3: "affected colleagues will be engaged in due course." So, no.`, '1:05 PM'], ['Tomas', `Engaged. Like a hostage negotiation.`, '1:05 PM'], ['Nadia', `Keiko's in a meeting with HR at 2. If anyone knows, she will. Or she'll have been told to say she doesn't.`, '1:08 PM'], ['Tomas', `Then we'll know by the look on her face.`, '1:09 PM']] },
    qs: [
      { q: `What is Tomas implying by calling "sunsetting" a verb "borrowed from software"?`, o: [`The memo was written by the IT department`, `The wording is impersonal and softens an unwelcome decision`, `The desk will be replaced by an application`, `He is unfamiliar with technical vocabulary`], a: 1, x: `Ironie : un jargon technique froid pour parler de la suppression d'un service et de ses personnes.` },
      { q: `What can be concluded from "affected colleagues will be engaged in due course"?`, o: [`The affected staff have already been informed`, `Those concerned will receive new contracts soon`, `The memo does not say who is affected or when they will be told`, `The desk will be kept open`], a: 2, x: `« in due course » reste vague : ni les personnes touchées ni le calendrier ne sont précisés.` },
      { q: `What does Nadia suggest about Keiko?`, o: [`She may know more but be asked not to say`, `She has been dismissed`, `She wrote the memo`, `She dislikes talking to colleagues`], a: 0, x: `« Or she'll have been told to say she doesn't » : Keiko pourrait savoir sans avoir le droit de parler.` },
    ] },
  { id: 'dz054', diff: 4, label: 'Loan terms', doc: { kind: 'notice', head: 'Meridian Bank — Education Loan, variable rate', title: 'Interest and repayment terms', body: `<p>The interest rate equals the benchmark rate plus a fixed margin of 2.4 percentage points and is reset on the first day of each quarter. Over the life of the loan the rate cannot exceed 11% or fall below 3.5%.</p><p>Repayment begins six months after graduation. Until then, interest accrues and is capitalised (added to the principal) annually, so that interest is subsequently charged on interest unless the borrower elects to pay it as it falls due. Voluntary prepayments carry no penalty and are applied first to accrued interest, then to principal.</p>` },
    qs: [
      { q: `The benchmark rate falls to 0.8%. What rate would the borrower pay?`, o: [`3.2%`, `0.8%`, `2.4%`, `3.5%`], a: 3, x: `0,8 + 2,4 = 3,2 %, mais le plancher de 3,5 % s'applique.` },
      { q: `What does capitalisation of interest mean for a borrower who pays nothing while studying?`, o: [`Interest stops being charged`, `Unpaid interest is added to the loan and then itself earns interest`, `The margin is reduced each year`, `The debt is converted into shares`], a: 1, x: `Capitaliser = ajouter les intérêts au principal ; les intérêts portent ensuite eux-mêmes intérêt.` },
      { q: `How is an early voluntary payment used?`, o: [`It first covers interest that has built up`, `It is applied to the principal only`, `It reduces the margin`, `It is subject to a penalty`], a: 0, x: `« applied first to accrued interest, then to principal » ; pas de pénalité.` },
    ] },
  { id: 'dz055', diff: 4, label: 'Email', doc: { kind: 'email', from: 'Dean Margaret Oyelaran', to: 'Heads of department', subject: 'Budget outlook for next year', body: `<p>Dear colleagues,</p><p>As you know, the University's state grant has remained flat for the third consecutive year, whereas our costs have not. After consulting the Finance Committee, the Faculty will pursue a programme of what the central administration calls "efficiency measures". In practice these comprise a freeze on recruitment to non-teaching posts, a review of modules with fewer than twelve enrolments, and a moratorium on discretionary travel funds.</p><p>No compulsory redundancies are planned. I would, however, be less than candid if I suggested that the next two years will be comfortable. I would urge you to send me your department's priorities by 30 June.</p>` },
    qs: [
      { q: `Why does the dean emphasise that the grant has been "flat"?`, o: [`It has grown too quickly`, `It has been withdrawn`, `It has not kept pace with rising costs, so it is effectively shrinking`, `It has been spent in advance`], a: 2, x: `Une subvention stable alors que les coûts augmentent équivaut à une baisse réelle.` },
      { q: `What does the dean say about job losses?`, o: [`They are impossible`, `Forced dismissals are not currently planned, but nothing is guaranteed`, `They will start in June`, `They will affect teaching staff only`], a: 1, x: `« are planned » ≠ « will never happen » : formule prudente, sans garantie.` },
      { q: `What is the effect of "I would be less than candid if I suggested the next two years will be comfortable"?`, o: [`It apologises for past mistakes`, `It promises financial recovery`, `It announces a precise cut`, `It warns that a difficult period lies ahead`], a: 3, x: `Litote : « less than candid » = ne pas dire la vérité ; la vérité est que les années seront difficiles.` },
    ] },
  { id: 'dz056', diff: 4, label: 'Syllabus excerpt', doc: { kind: 'notice', head: 'LAW 205 — Assessment', title: 'Calculation of final grades', body: `<p>The final grade is the weighted average of coursework (40%) and the final examination (60%). To pass the course, a student must score at least 40% on the final examination, whatever the coursework mark; a student who falls below that threshold receives an F irrespective of the weighted average.</p><p>Conversely, a student who scores 70% or above in the examination may have their lowest coursework mark replaced by the examination score, provided that the average of the remaining coursework marks is at least 50%.</p>` },
    qs: [
      { q: `What weighted average would a student obtain with 80% in coursework and 60% in the examination?`, o: [`68%`, `70%`, `72%`, `65%`], a: 0, x: `0,4 x 80 + 0,6 x 60 = 32 + 36 = 68 %.` },
      { q: `Which student can have a coursework mark replaced?`, o: [`Exam 65%, other coursework average 80%`, `Exam 85%, other coursework average 45%`, `Exam 78%, other coursework average 55%`, `Exam 38%, other coursework average 90%`], a: 2, x: `Il faut examen de 70 % ou plus ET moyenne du reste de la note continue d'au moins 50 %.` },
      { q: `Which statement is consistent with the policy?`, o: [`Excellent coursework can make up for a very weak exam`, `A student scoring 35% on the exam fails whatever the coursework result`, `The exam counts for 40% of the grade`, `Coursework marks can never be replaced`], a: 1, x: `Seuil de 40 % à l'examen : en dessous, F quel que soit le contrôle continu.` },
    ] },
  { id: 'dz057', diff: 4, label: 'Email', doc: { kind: 'email', from: 'People Operations', to: 'All employees', subject: 'Hybrid working policy from 1 September', body: `<p>Dear all,</p><p>From 1 September, employees will be expected to work on site at least three days a week, up from two. The days will be set by each team, not by individuals.</p><p>Exceptions may be granted by a Director where the nature of the role makes attendance impracticable, or where an employee has a documented medical or caring need; they are not, however, an entitlement, and will be reviewed annually. Colleagues on fully remote contracts are unaffected, although a change of role would trigger a reassessment. Managers are asked not to approve informal arrangements that run counter to the policy.</p>` },
    qs: [
      { q: `What will change for an employee on a fully remote contract?`, o: [`They must come in three days a week`, `Nothing, unless they move to another role`, `Their contract ends`, `They must come in two days a week`], a: 1, x: `Non concernés, mais un changement de poste entraînerait un réexamen.` },
      { q: `What does "they are not, however, an entitlement" imply about exceptions?`, o: [`They are granted automatically`, `They apply only to managers`, `They are discretionary even when a need is documented`, `They last forever`], a: 2, x: `Un besoin documenté n'ouvre pas de droit automatique : la Direction décide, et revoit chaque année.` },
      { q: `Why are managers asked not to approve informal arrangements?`, o: [`To prevent informal deals from undermining the policy`, `To reduce the number of managers`, `To encourage remote work`, `To save money on office space`], a: 0, x: `Des accords informels contraires à la règle videraient la politique de son sens.` },
    ] },
  { id: 'dz058', diff: 4, label: 'Text messages', doc: { kind: 'chat', head: 'Chat — Client reporting', msgs: [['Elise', `Quick sanity check before this goes to the client: can we say the fund "outperformed its benchmark" last year?`, '9:30 AM'], ['Hugo', `Technically, yes: 8.1% against 7.9%. But that's before fees. Net of fees it lagged by about 0.4.`, '9:33 AM'], ['Elise', `So "outperformed" is accurate on a gross basis.`, '9:34 AM'], ['Hugo', `Accurate, yes. Misleading without the qualifier, and Compliance won't wave it through. I'd say "delivered a gross return of 8.1%, slightly ahead of its benchmark" and put the net figure alongside.`, '9:37 AM'], ['Elise', `A mouthful, but I take the point. Could the net figure go in a footnote?`, '9:38 AM'], ['Hugo', `Footnotes are where disclosures go to die. Put it in the sentence.`, '9:39 AM']] },
    qs: [
      { q: `Why does Hugo hesitate to say the fund "outperformed its benchmark"?`, o: [`The fund lost money last year`, `The benchmark was calculated incorrectly`, `After fees the fund actually did worse than its benchmark`, `Compliance has banned the word`], a: 2, x: `Brut : 8,1 % contre 7,9 % ; net de frais, il est derrière d'environ 0,4 point.` },
      { q: `What does Hugo mean by "Accurate, yes. Misleading without the qualifier"?`, o: [`A statement can be literally true yet create a false impression`, `The statement contains a factual error`, `The qualifier makes the statement inaccurate`, `The figures should be rounded`], a: 0, x: `Une phrase exacte mais incomplète peut tromper : d'où le qualificatif « gross ».` },
      { q: `Why does Hugo reject the footnote idea?`, o: [`Footnotes are too expensive to print`, `The client never reads the sentence`, `Compliance forbids footnotes`, `Information in footnotes tends to go unnoticed`], a: 3, x: `Expression imagée : « where disclosures go to die » = c'est là que les informations se perdent.` },
    ] },
  { id: 'dz059', diff: 4, label: 'Health plan notice', doc: { kind: 'notice', head: 'Student Health Plan', title: 'How your deductible and coinsurance work', body: `<p>Before the plan pays towards most services, you must meet an annual deductible of $500. Thereafter you share costs through coinsurance: the plan pays 80% of allowed charges and you pay 20%, until you reach the annual out-of-pocket maximum of $2,500. That maximum includes your deductible and coinsurance but not your premiums, nor any charges above the allowed amount when you use an out-of-network provider.</p><p>Routine check-ups and a range of preventive services are covered in full and are not subject to the deductible.</p>` },
    qs: [
      { q: `Which service is paid for without the deductible being met?`, o: [`Emergency surgery`, `A preventive check-up`, `A visit to an out-of-network specialist`, `A prescription for a long-term illness`], a: 1, x: `Les soins préventifs sont couverts à 100 % sans franchise.` },
      { q: `After the deductible is met, how much does the student pay for a service with an allowed charge of $1,000?`, o: [`$800`, `$500`, `$200`, `$100`], a: 2, x: `Le régime paie 80 % ; l'étudiant paie 20 %, soit 200 $.` },
      { q: `Which of these does NOT count towards the $2,500 maximum?`, o: [`The deductible`, `Insurance premiums`, `Coinsurance payments`, `The student's own share of allowed charges`], a: 1, x: `Les primes et les dépassements hors réseau ne comptent pas dans le plafond.` },
    ] },
  { id: 'dz060', diff: 4, label: 'Email', doc: { kind: 'email', from: 'Rosalind Adeyemi, Programme Officer', to: 'Dr. Mensah', subject: 'Award of research grant: conditions', body: `<p>Dear Dr. Mensah,</p><p>I am pleased to confirm that the Foundation has approved your application, subject to the following conditions. The award of $180,000 over 24 months will be released in three tranches: 40% on signature, 30% on acceptance of the 12-month progress report, and the balance on receipt of the final report.</p><p>The Foundation reserves the right to withhold a tranche if milestones have not been met without a satisfactory explanation and, in cases of material misuse, to reclaim funds already disbursed. Equipment purchases above $5,000 require prior written approval. Any funds unspent at the end of the period must be returned unless a no-cost extension has been agreed.</p>` },
    qs: [
      { q: `How much will Dr. Mensah receive on signature?`, o: [`$54,000`, `$90,000`, `$72,000`, `$180,000`], a: 2, x: `40 % de 180 000 $ = 72 000 $.` },
      { q: `In what situation might the Foundation demand money back that has already been paid?`, o: [`If a milestone is delayed for a good reason`, `If the researcher misuses the funds in a serious way`, `If the final report is late`, `If a no-cost extension is requested`], a: 1, x: `Seul un « material misuse » permet de réclamer des fonds déjà versés ; un jalon manqué permet seulement de retenir une tranche.` },
      { q: `What must happen to money not spent by the end of the grant period?`, o: [`It may be kept by the researcher`, `It is carried over automatically`, `It must be returned unless an extension has been agreed`, `It is converted into a loan`], a: 2, x: `« must be returned unless a no-cost extension has been agreed ».` },
    ] },
);
})();
